function mdjResolveLibroKey_(libroKey) {
  const raw = String(libroKey || '').trim().toLowerCase();
  return raw === 'quinto_bachillerato_2' ? 'quinto_bachillerato_dup' : raw;
}

function mdjGetLibroByKey(libroKey) {
  const resolved = mdjResolveLibroKey_(libroKey);
  return MDJ_LIBROS.find(function(libro) {
    return libro.key === resolved;
  }) || null;
}

function mdjGetLibros() {
  return MDJ_LIBROS.map(function(libro) {
    return Object.assign({}, libro, {
      boletasFolderId: MDJ_BOLETAS_DRIVE.foldersByLibro[libro.key] || ''
    });
  });
}

