//  Colegio Mundo de Juguetes  |  agregar como nuevo archivo GAS
// ============================================================

/* ─────────────────────────────────────────────────────────────
   HELPER INTERNO
   Detecta la hoja de padrón dentro del SpreadSheet del libro.
   Ajusta NOMBRES_PADRON según la convención real de tus hojas.
───────────────────────────────────────────────────────────── */
function mdjGetPadronSheet_(ss) {
  var NOMBRES_PADRON = ['ALUMNOS', 'PADRÓN', 'PADRON', 'LISTA', 'ESTUDIANTES', 'PADRON GENERAL'];
  for (var i = 0; i < NOMBRES_PADRON.length; i++) {
    var s = ss.getSheetByName(NOMBRES_PADRON[i]);
    if (s) return s;
  }
  // Fallback: primera hoja no ignorada
  var ignoradas = (MDJ_APP && MDJ_APP.hojasIgnorar) ? MDJ_APP.hojasIgnorar : [];
  var todas = ss.getSheets();
  for (var j = 0; j < todas.length; j++) {
    if (ignoradas.indexOf(todas[j].getName()) === -1) return todas[j];
  }
  return null;
}

/* ─────────────────────────────────────────────────────────────
   HELPER: validar sesión admin
───────────────────────────────────────────────────────────── */
function mdjValidarSesionAdmin_(token) {
  var session = mdjGetSession(token);
  if (!session || !session.ok) return 'Sesión inválida.';
  var user = session.user || session.usuario || session.sessionUser;
  if (!user || String(user.rol || '').toLowerCase() !== 'admin') return 'Sin permisos de administrador.';
  return null; // null = OK
}

/* ─────────────────────────────────────────────────────────────
   1. ACTUALIZAR NOMBRE DE UN ALUMNO (individual)
───────────────────────────────────────────────────────────── */
/**
 * @param {string} token
 * @param {string} libroKey
 * @param {number} rowNumber  – fila real en la hoja (1-based)
 * @param {string} nuevoNombre
 * @returns {{ ok, message }}
 */
function mdjUpdateStudentName(token, libroKey, rowNumber, nuevoNombre) {
  try {
    var err = mdjValidarSesionAdmin_(token);
    if (err) return { ok: false, message: err };

    var libro = mdjGetLibroByKey(libroKey);
    if (!libro) return { ok: false, message: 'Libro no encontrado: ' + libroKey };

    var row    = parseInt(rowNumber, 10);
    var nombre = String(nuevoNombre || '').trim();
    if (!row || row < 2) return { ok: false, message: 'Número de fila inválido.' };
    if (!nombre)         return { ok: false, message: 'El nombre no puede estar vacío.' };

    var ss    = SpreadsheetApp.openById(libro.driveId);
    var sheet = mdjGetPadronSheet_(ss);
    if (!sheet) return { ok: false, message: 'No se encontró la hoja de padrón.' };

    sheet.getRange(row, 2).setValue(nombre); // columna B = nombre
    SpreadsheetApp.flush();

    return { ok: true, message: 'Nombre actualizado correctamente.' };
  } catch (e) {
    return { ok: false, message: 'Error: ' + e.message };
  }
}

/* ─────────────────────────────────────────────────────────────
   2. ACTUALIZAR NOMBRES EN LOTE
───────────────────────────────────────────────────────────── */
/**
 * @param {string} token
 * @param {string} libroKey
 * @param {{ rowNumber: number, nombre: string }[]} cambios
 * @returns {{ ok, message, actualizados, errores }}
 */
function mdjUpdateStudentNamesBatch(token, libroKey, cambios) {
  try {
    var err = mdjValidarSesionAdmin_(token);
    if (err) return { ok: false, message: err };

    var libro = mdjGetLibroByKey(libroKey);
    if (!libro) return { ok: false, message: 'Libro no encontrado: ' + libroKey };

    if (!Array.isArray(cambios) || !cambios.length) return { ok: false, message: 'Sin cambios.' };

    var ss    = SpreadsheetApp.openById(libro.driveId);
    var sheet = mdjGetPadronSheet_(ss);
    if (!sheet) return { ok: false, message: 'No se encontró la hoja de padrón.' };

    var actualizados = 0, erroresLocal = 0;
    cambios.forEach(function(c) {
      try {
        var row    = parseInt(c.rowNumber, 10);
        var nombre = String(c.nombre || '').trim();
        if (!row || row < 2 || !nombre) { erroresLocal++; return; }
        sheet.getRange(row, 2).setValue(nombre);
        actualizados++;
      } catch (_) { erroresLocal++; }
    });
    SpreadsheetApp.flush();

    return {
      ok:           actualizados > 0 || erroresLocal === 0,
      message:      'Actualizados: ' + actualizados + '. Errores: ' + erroresLocal + '.',
      actualizados: actualizados,
      errores:      erroresLocal
    };
  } catch (e) {
    return { ok: false, message: 'Error: ' + e.message };
  }
}

/* ─────────────────────────────────────────────────────────────
   3. AGREGAR NUEVO ALUMNO
   Agrega una fila al final del padrón con número y nombre.
   Devuelve el rowNumber real donde quedó insertado.
───────────────────────────────────────────────────────────── */
/**
 * @param {string} token
 * @param {string} libroKey
 * @param {string} numero   – código o número de lista (puede ser vacío)
 * @param {string} nombre   – nombre completo (requerido)
 * @returns {{ ok, message, rowNumber }}
 */
function mdjAddStudent(token, libroKey, numero, nombre) {
  try {
    var err = mdjValidarSesionAdmin_(token);
    if (err) return { ok: false, message: err };

    var libro = mdjGetLibroByKey(libroKey);
    if (!libro) return { ok: false, message: 'Libro no encontrado: ' + libroKey };

    var nombreLimpio  = String(nombre  || '').trim();
    var numeroLimpio  = String(numero  || '').trim();
    if (!nombreLimpio) return { ok: false, message: 'El nombre no puede estar vacío.' };

    var ss    = SpreadsheetApp.openById(libro.driveId);
    var sheet = mdjGetPadronSheet_(ss);
    if (!sheet) return { ok: false, message: 'No se encontró la hoja de padrón.' };

    // Encontrar la primera fila vacía en columna B (nombre)
    var lastRow = sheet.getLastRow();
    var newRow  = lastRow + 1;

    // Columna A = número, columna B = nombre
    // Ajusta los índices de columna si tu hoja usa otro orden
    if (numeroLimpio) sheet.getRange(newRow, 1).setValue(numeroLimpio);
    sheet.getRange(newRow, 2).setValue(nombreLimpio);
    SpreadsheetApp.flush();

    return { ok: true, message: 'Alumno agregado en fila ' + newRow + '.', rowNumber: newRow };
  } catch (e) {
    return { ok: false, message: 'Error: ' + e.message };
  }
}

/* ─────────────────────────────────────────────────────────────
   4. ELIMINAR ALUMNO (borrar fila completa)
   ⚠ IRREVERSIBLE: borra la fila entera de la hoja.
   Todas las filas debajo se desplazan hacia arriba.
───────────────────────────────────────────────────────────── */
/**
 * @param {string} token
 * @param {string} libroKey
 * @param {number} rowNumber – fila real a eliminar
 * @returns {{ ok, message }}
 */
function mdjDeleteStudent(token, libroKey, rowNumber) {
  try {
    var err = mdjValidarSesionAdmin_(token);
    if (err) return { ok: false, message: err };

    var libro = mdjGetLibroByKey(libroKey);
    if (!libro) return { ok: false, message: 'Libro no encontrado: ' + libroKey };

    var row = parseInt(rowNumber, 10);
    if (!row || row < 2) return { ok: false, message: 'Número de fila inválido (no se puede borrar la fila 1).' };

    var ss    = SpreadsheetApp.openById(libro.driveId);
    var sheet = mdjGetPadronSheet_(ss);
    if (!sheet) return { ok: false, message: 'No se encontró la hoja de padrón.' };

    var lastRow = sheet.getLastRow();
    if (row > lastRow) return { ok: false, message: 'La fila ' + row + ' no existe en la hoja (última fila: ' + lastRow + ').' };

    sheet.deleteRow(row);
    SpreadsheetApp.flush();

    return { ok: true, message: 'Alumno eliminado (fila ' + row + ' borrada).' };
  } catch (e) {
    return { ok: false, message: 'Error: ' + e.message };
  }
}